        } else if (!inl3_form.equals("edgelist1") && !inl3_form.equals("fullmatrix")) {
            report.logIssue(new Issue(NbBundle.getMessage(ImporterDL.class, "importerDL_error_badformat", inl3_form), Issue.Level.SEVERE));
        } else if (inl3_form.equals("edgelist1")) {
            format = Format.EDGELIST1;
        } else if (inl3_form.equals("fullmatrix")) {
            format = Format.FULLMATRIX;
        }
        try {
            String inl3_nArg = headerMap.get("n");
            numNodes = Integer.parseInt(inl3_nArg);
        } catch (Exception inl3_e) {
            report.logIssue(new Issue(NbBundle.getMessage(ImporterDL.class, "importerDL_error_nmissing"), Issue.Level.SEVERE));
        }
        String inl3_mats = headerMap.get("nm");
        if (inl3_mats != null) {
            try {
                numMatricies = Integer.parseInt(inl3_mats);
            } catch (Exception inl3_e) {
                report.logIssue(new Issue(NbBundle.getMessage(ImporterDL.class, "importerDL_error_mmissing"), Issue.Level.SEVERE));
            }
        } else {
            numMatricies = 1;
        }
    }
    if (lines.get(i).toLowerCase().trim().endsWith("labels:") && lines.size() > i + 1) {
        {
            String inl2_arg0 = lines.get(++i);
            StringTokenizer inl2_labelkonizer = new StringTokenizer(inl2_arg0, ",");
            if (inl2_labelkonizer.countTokens() != numNodes) {
                report.logIssue(new Issue(NbBundle.getMessage(ImporterDL.class, "importerDL_error_labelscount", inl2_labelkonizer.countTokens(), numNodes), Issue.Level.SEVERE));
            }
            int inl2_nodeCount = 0;
            while (inl2_labelkonizer.hasMoreTokens()) {
                String inl2_label = inl2_labelkonizer.nextToken();
                inl2_nodeCount++;
                NodeDraft inl2_nodeDraft = container.factory().newNodeDraft("" + inl2_nodeCount);
                inl2_nodeDraft.setLabel(inl2_label);
                container.addNode(inl2_nodeDraft);
            }
        }
    }
    int dataLineStart = -1;
    for (; i < lines.size(); i++) {
        String line = lines.get(i).toLowerCase();
        if (line.trim().endsWith("data:")) {
            dataLineStart = i + 1;
            break;
        }
    }
    if (dataLineStart == -1) {
        report.logIssue(new Issue(NbBundle.getMessage(ImporterDL.class, "importerDL_error_nodata"), Issue.Level.SEVERE));
    } else if (lines.size() > dataLineStart) {
        dataLineStartDelta = dataLineStart + 1;
        lines = lines.subList(dataLineStart, lines.size());
        if (format.equals(Format.FULLMATRIX)) {
            {
                List<String> inl1_arg0 = lines;
                int inl1_startTime = 0;
                for (int inl1_i = 0; inl1_i < inl1_arg0.size(); inl1_i++) {
                    int inl1_rowNum = 0;
                    for (; inl1_i < inl1_arg0.size() && !inl1_arg0.get(inl1_i).trim().equals("!"); inl1_i++) {
                        if (inl1_rowNum <= numNodes) {
                            readMatrixRow(inl1_arg0.get(inl1_i), inl1_i, inl1_rowNum, inl1_startTime, inl1_startTime + 1);
                            inl1_rowNum++;
                        } else {
                            report.logIssue(new Issue(NbBundle.getMessage(ImporterDL.class, "importerDL_error_matrixrowscount", inl1_rowNum, numNodes), Issue.Level.SEVERE));
                            break;
                        }
                    }
                    if (inl1_rowNum < numNodes) {
                        report.logIssue(new Issue(NbBundle.getMessage(ImporterDL.class, "importerDL_error_matrixrowscount2", inl1_rowNum, numNodes), Issue.Level.SEVERE));
                    }
                    inl1_startTime++;
                }
                if (inl1_startTime != numMatricies) {
                    report.logIssue(new Issue(NbBundle.getMessage(ImporterDL.class, "importerDL_error_matriciescount", inl1_startTime, numMatricies), Issue.Level.SEVERE));
                }
            }
        } else if (format.equals(Format.EDGELIST1)) {
            {
                List<String> inl0_arg0 = lines;
                int inl0_startTime = 0;
                for (int inl0_i = 0; inl0_i < inl0_arg0.size(); inl0_i++) {
                    for (; inl0_i < inl0_arg0.size() && !inl0_arg0.get(inl0_i).trim().equals("!"); inl0_i++) {
                        readEdgelistRow(inl0_arg0.get(inl0_i), inl0_i, inl0_startTime, inl0_startTime + 1);
                    }
