private void moveNodeTo(int node, StatisticalInferenceClustering.Community to) {
    {
        int inl1_arg0 = node;
        StatisticalInferenceClustering.Community inl1_community = nodeCommunities[inl1_arg0];
        inl1_community.internalWeightSum -= nodeConnectionsWeight[inl1_arg0].getOrDefault(inl1_community, 0.f);
        for (ComputationEdge inl1_e : topology[inl1_arg0]) {
            int inl1_neighbor = inl1_e.target;
            Float inl1_edgesTo = nodeConnectionsWeight[inl1_neighbor].get(inl1_community);
            Integer inl1_countEdgesTo = nodeConnectionsCount[inl1_neighbor].get(inl1_community);
            if (inl1_countEdgesTo - 1 == 0) {
                nodeConnectionsWeight[inl1_neighbor].remove(inl1_community);
                nodeConnectionsCount[inl1_neighbor].remove(inl1_community);
            } else {
                nodeConnectionsWeight[inl1_neighbor].put(inl1_community, inl1_edgesTo - inl1_e.weight);
                nodeConnectionsCount[inl1_neighbor].put(inl1_community, inl1_countEdgesTo - 1);
            }
            StatisticalInferenceClustering.Community inl1_adjCom = nodeCommunities[inl1_neighbor];
            Float inl1_oEdgesto = inl1_adjCom.connectionsWeight.get(inl1_community);
            Integer inl1_oCountEdgesto = inl1_adjCom.connectionsCount.get(inl1_community);
            if (inl1_oCountEdgesto - 1 == 0) {
                inl1_adjCom.connectionsWeight.remove(inl1_community);
                inl1_adjCom.connectionsCount.remove(inl1_community);
            } else {
                inl1_adjCom.connectionsWeight.put(inl1_community, inl1_oEdgesto - inl1_e.weight);
                inl1_adjCom.connectionsCount.put(inl1_community, inl1_oCountEdgesto - 1);
            }
            if (inl1_arg0 == inl1_neighbor) {
                continue;
            }
            if (inl1_adjCom != inl1_community) {
                Float inl1_comEdgesto = inl1_community.connectionsWeight.get(inl1_adjCom);
                Integer inl1_comCountEdgesto = inl1_community.connectionsCount.get(inl1_adjCom);
                if (inl1_comCountEdgesto - 1 == 0) {
                    inl1_community.connectionsWeight.remove(inl1_adjCom);
                    inl1_community.connectionsCount.remove(inl1_adjCom);
                } else {
                    inl1_community.connectionsWeight.put(inl1_adjCom, inl1_comEdgesto - inl1_e.weight);
                    inl1_community.connectionsCount.put(inl1_adjCom, inl1_comCountEdgesto - 1);
                }
            }
            Float inl1_nodeEgesTo = nodeConnectionsWeight[inl1_arg0].get(inl1_adjCom);
            Integer inl1_nodeCountEgesTo = nodeConnectionsCount[inl1_arg0].get(inl1_adjCom);
            if (inl1_nodeCountEgesTo - 1 == 0) {
                nodeConnectionsWeight[inl1_arg0].remove(inl1_adjCom);
                nodeConnectionsCount[inl1_arg0].remove(inl1_adjCom);
            } else {
                nodeConnectionsWeight[inl1_arg0].put(inl1_adjCom, inl1_nodeEgesTo - inl1_e.weight);
                nodeConnectionsCount[inl1_arg0].put(inl1_adjCom, inl1_nodeCountEgesTo - 1);
            }
        }
        inl1_community.remove(inl1_arg0);
    }
    {
        int inl0_arg0 = node;
        StatisticalInferenceClustering.Community inl0_arg1 = to;
        inl0_arg1.add(inl0_arg0);
        nodeCommunities[inl0_arg0] = inl0_arg1;
        for (ComputationEdge inl0_e : topology[inl0_arg0]) {
            int inl0_neighbor = inl0_e.target;
            nodeConnectionsWeight[inl0_neighbor].merge(inl0_arg1, inl0_e.weight, Float::sum);
            nodeConnectionsCount[inl0_neighbor].merge(inl0_arg1, 1, Integer::sum);
            StatisticalInferenceClustering.Community inl0_adjCom = nodeCommunities[inl0_neighbor];
            inl0_adjCom.connectionsWeight.merge(inl0_arg1, inl0_e.weight, Float::sum);
            inl0_adjCom.connectionsCount.merge(inl0_arg1, 1, Integer::sum);
            if (inl0_arg0 == inl0_neighbor) {
                continue;
            }
            nodeConnectionsWeight[inl0_arg0].merge(inl0_adjCom, inl0_e.weight, Float::sum);
            nodeConnectionsCount[inl0_arg0].merge(inl0_adjCom, 1, Integer::sum);
            if (inl0_arg1 != inl0_adjCom) {
                inl0_arg1.connectionsWeight.merge(inl0_adjCom, inl0_e.weight, Float::sum);
                inl0_arg1.connectionsCount.merge(inl0_adjCom, 1, Integer::sum);
            }
        }
        inl0_arg1.internalWeightSum += nodeConnectionsWeight[inl0_arg0].getOrDefault(inl0_arg1, 0.f);
    }
}

