public void fitSlicesX(int nbins) {
    fithistogram = originalhistogram.rebinX(nbins);
    slices = fithistogram.getSlicesX();
    axis = fithistogram.getXAxis();
    if (autorangemin && slices.size() > 0) {
        min = slices.get(0).getxAxis().min();
    }
    if (autorangemax && slices.size() > 0) {
        max = slices.get(0).getxAxis().max();
    }
    if (autorangeminbin && slices.size() > 0) {
        minBin = 0;
    }
    if (autorangemaxbin) {
        maxBin = slices.size();
    }
    {
        List<Callable<Object>> inl0_taskList = new ArrayList<Callable<Object>>(slices.size());
        ArrayList<Future<Object>> inl0_tasks = new ArrayList<Future<Object>>();
        for (int inl0_i = 0; inl0_i < slices.size(); inl0_i++) {
            System.out.println(inl0_i + " " + minBin + " " + maxBin);
            if (inl0_i >= minBin && inl0_i < maxBin) {
                H1F inl0_slice = slices.get(inl0_i);
                if (inl0_slice.getIntegral() > minEvents) {
                    ResultSetter inl0_setter = new ResultSetter() {

                        public void setResult(H1F histogram, F1D fit, int fitNumber) {
                            FitResults inl0_result = new FitResults();
                            inl0_result.setData(histogram);
                            inl0_result.setFunction(fit);
                            inl0_result.setPoint(axis.getBinCenter(fitNumber));
                            if ((fit.getChiSquare() / (double) fit.getNDF()) < maxChiSquare) {
                                fitResults.add(inl0_result);
                            }
                        }
                    };
                    FitThread inl0_temp = new FitThread();
                    inl0_temp.setN(inl0_i);
                    inl0_temp.setHistogram(inl0_slice);
                    inl0_temp.setResultSetter(inl0_setter);
                    inl0_temp.setOptions(this.fitMode);
                    inl0_temp.setFitter(new F1D("f1", modes[mode], min, max));
                    threads.add(inl0_temp);
                }
            }
        }
        ExecutorService inl0_threadPool = Executors.newFixedThreadPool(nthreads);
        for (FitThread inl0_thread : threads) {
            inl0_taskList.add(Executors.callable(inl0_thread));
            @SuppressWarnings("unchecked")
            Future<Object> inl0_x = (Future<Object>) inl0_threadPool.submit(inl0_thread);
            inl0_tasks.add(inl0_x);
        }
        for (FitThread inl0_thread : threads) {
            try {
                inl0_thread.join();
            } catch (InterruptedException inl0_e) {
                inl0_e.printStackTrace();
            }
        }
        awaitTerminationAfterShutdown(inl0_threadPool);
        fitResults.sort(Comparator.comparing(FitResults::getPoint));
    }
}

@Override
public void paint(Graphics g) {
    try {
        Long st = System.currentTimeMillis();
        Graphics2D g2d = (Graphics2D) g;
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int w = this.getSize().width;
        int h = this.getSize().height;
        g2d.setColor(GStyle.getCanvasBackgroundColor());
        g2d.fillRect(0, 0, w, h);
        {
            int inl0_arg0 = w;
            int inl0_arg1 = h;
            int inl0_pcounter = 0;
            int inl0_startX = 5;
            int inl0_minY = 5;
            int inl0_rW = inl0_arg0 - inl0_startX;
            int inl0_rH = inl0_arg1 - inl0_minY;
            for (int inl0_ir = 0; inl0_ir < ec_ROWS; inl0_ir++) {
                for (int inl0_ic = 0; inl0_ic < ec_COLUMNS; inl0_ic++) {
                    double inl0_x = inl0_ic * (inl0_rW / ((double) ec_COLUMNS));
                    double inl0_xe = (inl0_ic + 1) * (inl0_rW / ((double) ec_COLUMNS));
                    double inl0_y = inl0_ir * (inl0_rH / ((double) ec_ROWS));
                    double inl0_ye = (inl0_ir + 1) * (inl0_rH / ((double) ec_ROWS));
                    canvasPads.get(inl0_pcounter).setDimension((int) inl0_x + inl0_startX, (int) inl0_y - inl0_minY, (int) (inl0_xe - inl0_x), (int) (inl0_ye - inl0_y));
                    inl0_pcounter++;
                }
            }
        }
        PadMargins margins = new PadMargins();
        for (int i = 0; i < canvasPads.size(); i++) {
            EmbeddedPad pad = canvasPads.get(i);
            pad.getAxisFrame().updateMargins(g2d);
            margins.marginFit(pad.getAxisFrame().getFrameMargins());
        }
        for (int i = 0; i < canvasPads.size(); i++) {
            EmbeddedPad pad = canvasPads.get(i);
            pad.getAxisFrame().setAxisMargins(margins);
            pad.setMargins(margins);
            margins.marginFit(pad.getAxisFrame().getFrameMargins());
        }
        for (int i = 0; i < canvasPads.size(); i++) {
            EmbeddedPad pad = canvasPads.get(i);
            pad.getAxisFrame().setAxisMargins(margins);
            pad.setMargins(margins);
            pad.draw(g2d);
        }
        Long et = System.currentTimeMillis();
        Long paintingTime = (et - st);
        paintingTimeSum += paintingTime;
        samples++;
        double average = (double) paintingTimeSum / (double) samples;
        if (showFPS) {
            g2d.setColor(Color.WHITE);
            g2d.fillRect(0, 0, 70, 32);
            g2d.setColor(Color.BLACK);
            g2d.drawRect(0, 0, 70, 32);
            g2d.setColor(Color.BLUE);
            g2d.drawString(String.format("%d FPS", (int) (1.0 / (((double) paintingTime) / 1000.0))), 5, 14);
            g2d.drawString(String.format("%4.2f Avg", (1.0 / ((average) / 1000.0))), 5, 28);
        }
        paintingTime += paintingTime;
        numberOfPaints++;
    } catch (Exception e) {
        System.out.println("[EmbeddedCanvas] ---> ooops");
        System.out.println(e);
    }
}

