public List<Double> getAxisMinorTicks() {
    if (this.isLogarithmic == false) {
        {
            int inl1_nticks = this.axisLabels.getTicks().size();
            List<Double> inl1_minorTicks = new ArrayList<Double>();
            if (inl1_nticks >= 2) {
                double inl1_cTick = axisLabels.getTicks().get(0);
                double inl1_nTick = axisLabels.getTicks().get(1);
                double inl1_step = Math.abs(inl1_nTick - inl1_cTick) / 4.0;
                for (int inl1_i = 0; inl1_i < inl1_nticks - 1; inl1_i++) {
                    inl1_cTick = axisLabels.getTicks().get(inl1_i);
                    inl1_nTick = axisLabels.getTicks().get(inl1_i + 1);
                    for (int inl1_m = 0; inl1_m < 3; inl1_m++) {
                        inl1_minorTicks.add(inl1_cTick + inl1_step * (inl1_m + 1));
                    }
                }
                inl1_cTick = inl1_nTick;
                int inl1_ncount = 0;
                while (inl1_cTick < this.axisRange.getMax() && inl1_ncount < 10) {
                    inl1_cTick += inl1_step;
                    if (inl1_cTick < axisRange.getMax())
                        inl1_minorTicks.add(inl1_cTick);
                    inl1_ncount++;
                }
                inl1_cTick = axisLabels.getTicks().get(0);
                inl1_ncount = 0;
                while (inl1_cTick > axisRange.getMin() && inl1_ncount < 10) {
                    inl1_cTick -= inl1_step;
                    if (inl1_cTick > axisRange.getMin())
                        inl1_minorTicks.add(inl1_cTick);
                }
            }
            return inl1_minorTicks;
        }
    } else {
        {
            List<Double> inl0_minorTicks = new ArrayList<Double>();
            List<Double> inl0_majorTicks = axisLabels.getTicks();
            for (int inl0_i = 0; inl0_i < inl0_majorTicks.size() - 1; inl0_i++) {
                for (int inl0_k = 2; inl0_k < 10; inl0_k++) {
                    double inl0_tick = (inl0_majorTicks.get(inl0_i) * inl0_k);
                    inl0_minorTicks.add(inl0_tick);
                }
            }
            return inl0_minorTicks;
        }
    }
}

