public void calculateMaximumFlow(V source, V sink) {
    if (!network.containsVertex(source)) {
        throw new IllegalArgumentException("invalid source (null or not from this network)");
    }
    if (!network.containsVertex(sink)) {
        throw new IllegalArgumentException("invalid sink (null or not from this network)");
    }
    if (source.equals(sink)) {
        throw new IllegalArgumentException("source is equal to sink");
    }
    currentSource = indexer.get(source);
    currentSink = indexer.get(sink);
    for (int i = 0; i < numNodes; i++) {
        for (Arc currentArc : nodes.get(i).outgoingArcs) {
            currentArc.flow = 0.0;
        }
    }
    maximumFlowValue = 0.0;
    for (; ; ) {
        {
            for (int inl1_i = 0; inl1_i < numNodes; inl1_i++) {
                nodes.get(inl1_i).visited = false;
            }
            Queue<Integer> inl1_queue = new LinkedList<Integer>();
            inl1_queue.offer(currentSource);
            nodes.get(currentSource).visited = true;
            nodes.get(currentSource).flowAmount = Double.POSITIVE_INFINITY;
            while (inl1_queue.size() != 0) {
                int inl1_currentNode = inl1_queue.poll();
                for (Arc inl1_currentArc : nodes.get(inl1_currentNode).outgoingArcs) {
                    if ((inl1_currentArc.flow + epsilon) < inl1_currentArc.capacity) {
                        if (!nodes.get(inl1_currentArc.head).visited) {
                            nodes.get(inl1_currentArc.head).visited = true;
                            nodes.get(inl1_currentArc.head).flowAmount = Math.min(nodes.get(inl1_currentNode).flowAmount, inl1_currentArc.capacity - inl1_currentArc.flow);
                            nodes.get(inl1_currentArc.head).lastArc = inl1_currentArc;
                            inl1_queue.add(inl1_currentArc.head);
                        }
                    }
                }
            }
        }
        if (!nodes.get(currentSink).visited) {
            maximumFlow = new HashMap<E, Double>();
            for (int i = 0; i < numNodes; i++) {
                for (Arc currentArc : nodes.get(i).outgoingArcs) {
                    if (currentArc.prototype != null) {
                        maximumFlow.put(currentArc.prototype, currentArc.flow);
                    }
                }
            }
            return;
        }
        {
            double inl0_deltaFlow = nodes.get(currentSink).flowAmount;
            maximumFlowValue += inl0_deltaFlow;
            int inl0_currentNode = currentSink;
            while (inl0_currentNode != currentSource) {
                nodes.get(inl0_currentNode).lastArc.flow += inl0_deltaFlow;
                nodes.get(inl0_currentNode).lastArc.reversed.flow -= inl0_deltaFlow;
                inl0_currentNode = nodes.get(inl0_currentNode).lastArc.tail;
            }
        }
    }
}

public List<GraphPath<V, E>> getPaths(V endVertex) {
    {
        V inl0_arg0 = endVertex;
        if (inl0_arg0 == null) {
            throw new NullPointerException("endVertex is null");
        }
        if (inl0_arg0.equals(this.startVertex)) {
