        }
        if (!this.graph.vertexSet().contains(inl0_arg0)) {
            throw new IllegalArgumentException("Graph must contain the end vertex!");
        }
    }
    KShortestPathsIterator<V, E> iter = new KShortestPathsIterator<V, E>(this.graph, this.startVertex, endVertex, this.nPaths);
    for (int passNumber = 1; (passNumber <= this.nMaxHops) && iter.hasNext(); passNumber++) {
        iter.next();
    }
    List<RankingPathElement<V, E>> list = iter.getPathElements(endVertex);
    if (list == null) {
        return null;
    }
    List<GraphPath<V, E>> pathList = new ArrayList<GraphPath<V, E>>();
    for (RankingPathElement<V, E> element : list) {
        pathList.add(new PathWrapper(element));
    }
    return pathList;
}

